import React, { useState, useEffect, useMemo } from 'react';
import {
  ShieldCheck,
  CreditCard,
  User,
  FileCheck,
  AlertCircle,
  CheckCircle2,
  Building2,
  Sparkles,
  RefreshCw,
  Info,
  Lock,
  ChevronRight,
  Fingerprint,
  TrendingUp,
  Award,
  Mail,
  Phone,
  MapPin,
  HelpCircle
} from 'lucide-react';

interface CreditScoreResult {
  score: number;
  rating: 'Poor' | 'Fair' | 'Good' | 'Very Good' | 'Excellent';
  bureau: string;
  lastUpdated: string;
  status: 'OPTIMAL' | 'MODERATE' | 'CRITICAL';
  factors: string[];
}

interface FormData {
  fullName: string;
  email: string;
  phone: string;
  panNumber: string;
  aadhaarNumber: string;
  address: string;
  agreeTerms: boolean;
}

export default function CustomerKYCForm() {
  const [formData, setFormData] = useState<FormData>({
    fullName: 'Ananya Sharma',
    email: 'ananya.sharma@example.com',
    phone: '+91 98765 43210',
    panNumber: 'ABCDE1234F',
    aadhaarNumber: '',
    address: '402, Cyber Heights, Hitec City, Hyderabad, 500081',
    agreeTerms: false
  });

  const [touched, setTouched] = useState<Record<string, boolean>>({});
  const [aadhaarError, setAadhaarError] = useState<string>('');
  const [isFetchingScore, setIsFetchingScore] = useState<boolean>(false);
  const [creditScoreData, setCreditScoreData] = useState<CreditScoreResult | null>(null);
  const [isSubmitting, setIsSubmitting] = useState<boolean>(false);
  const [isSubmitted, setIsSubmitted] = useState<boolean>(false);
  const [showTooltip, setShowTooltip] = useState<boolean>(false);

  // Aadhaar Regex: Exactly 12 numeric digits
  const AADHAAR_REGEX = /^\d{12}$/;

  // Real-time Aadhaar validation
  useEffect(() => {
    const rawDigits = formData.aadhaarNumber.replace(/\s+/g, '');

    if (!touched.aadhaarNumber && rawDigits.length === 0) {
      setAadhaarError('');
      return;
    }

    if (rawDigits.length === 0) {
      setAadhaarError('Aadhaar number is required.');
    } else if (!/^\d+$/.test(rawDigits)) {
      setAadhaarError('Aadhaar must contain numeric digits only.');
    } else if (rawDigits.length !== 12) {
      setAadhaarError(`Must be exactly 12 digits (currently ${rawDigits.length}/12).`);
    } else if (!AADHAAR_REGEX.test(rawDigits)) {
      setAadhaarError('Invalid Aadhaar number format.');
    } else {
      setAadhaarError('');
    }
  }, [formData.aadhaarNumber, touched.aadhaarNumber]);

  // Format Aadhaar for display (1234 5678 9012)
  const handleAadhaarChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value;
    // Remove non-numeric characters and cap at 12 digits
    const cleanDigits = value.replace(/\D/g, '').slice(0, 12);

    // Format with spaces every 4 digits for readability
    const formatted = cleanDigits.replace(/(\d{4})(?=\d)/g, '$1 ');

    setFormData(prev => ({ ...prev, aadhaarNumber: formatted }));
  };

  const rawAadhaar = useMemo(() => {
    return formData.aadhaarNumber.replace(/\s+/g, '');
  }, [formData.aadhaarNumber]);

  const isAadhaarValid = useMemo(() => {
    return AADHAAR_REGEX.test(rawAadhaar);
  }, [rawAadhaar]);

  // Trigger simulated Bureau pull when Aadhaar becomes valid
  useEffect(() => {
    if (isAadhaarValid && !creditScoreData && !isFetchingScore) {
      fetchCreditBureauScore();
    }
  }, [isAadhaarValid]);

  const fetchCreditBureauScore = () => {
    setIsFetchingScore(true);
    setTimeout(() => {
      // Deterministic or pseudo-random credit score for demo
      setCreditScoreData({
        score: 782,
        rating: 'Very Good',
        bureau: 'Experian / CIBIL Partner Bureau',
        lastUpdated: new Date().toLocaleDateString('en-US', {
          month: 'short',
          day: 'numeric',
          year: 'numeric'
        }),
        status: 'OPTIMAL',
        factors: ['0 Overdue Accounts', 'Low Credit Utilization (14%)', '99.4% On-time Payment History']
      });
      setIsFetchingScore(false);
    }, 1200);
  };

  const handleBlur = (field: string) => {
    setTouched(prev => ({ ...prev, [field]: true }));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setTouched({
      aadhaarNumber: true
    });

    if (!isAadhaarValid) {
      return;
    }

    setIsSubmitting(true);
    setTimeout(() => {
      setIsSubmitting(false);
      setIsSubmitted(true);
    }, 1500);
  };

  // Gauge math for Credit Score (300 to 850 range)
  const getScorePercentage = (score: number) => {
    const min = 300;
    const max = 850;
    const clamped = Math.min(Math.max(score, min), max);
    return ((clamped - min) / (max - min)) * 100;
  };

  const getScoreColor = (score: number) => {
    if (score >= 750) return { bg: 'bg-emerald-500', text: 'text-emerald-700', border: 'border-emerald-200', gradient: 'from-emerald-50 to-teal-50', ring: 'ring-emerald-500' };
    if (score >= 650) return { bg: 'bg-blue-500', text: 'text-blue-700', border: 'border-blue-200', gradient: 'from-blue-50 to-indigo-50', ring: 'ring-blue-500' };
    if (score >= 550) return { bg: 'bg-amber-500', text: 'text-amber-700', border: 'border-amber-200', gradient: 'from-amber-50 to-orange-50', ring: 'ring-amber-500' };
    return { bg: 'bg-rose-500', text: 'text-rose-700', border: 'border-rose-200', gradient: 'from-rose-50 to-red-50', ring: 'ring-rose-500' };
  };

  if (isSubmitted) {
    return (
      <div className="min-h-screen bg-slate-50 flex items-center justify-center p-4 font-sans">
        <div className="max-w-md w-full bg-white rounded-2xl shadow-xl border border-slate-100 p-8 text-center animate-in fade-in zoom-in-95 duration-300">
          <div className="w-16 h-16 bg-emerald-100 text-emerald-600 rounded-full flex items-center justify-center mx-auto mb-4">
            <CheckCircle2 className="w-10 h-10" />
          </div>
          <h2 className="text-2xl font-bold text-slate-900 mb-2">KYC Form Submitted</h2>
          <p className="text-slate-600 mb-6 text-sm leading-relaxed">
            Aadhaar verification details and calculated credit scores have been successfully synchronized with the compliance service.
          </p>
          <div className="bg-slate-50 border border-slate-200/80 rounded-xl p-4 text-left mb-6 space-y-2 text-xs text-slate-700">
            <div className="flex justify-between">
              <span className="text-slate-500">Aadhaar Verified:</span>
              <span className="font-mono font-medium text-slate-900">XXXX-XXXX-{rawAadhaar.slice(-4)}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-500">Bureau Credit Score:</span>
              <span className="font-semibold text-emerald-600">{creditScoreData?.score} ({creditScoreData?.rating})</span>
            </div>
            <div className="flex justify-between">
              <span className="text-slate-500">Verification Status:</span>
              <span className="inline-flex items-center text-emerald-700 font-medium bg-emerald-50 px-2 py-0.5 rounded-full border border-emerald-200">
                Verified & Passed
              </span>
            </div>
          </div>
          <button
            onClick={() => {
              setIsSubmitted(false);
              setFormData(prev => ({ ...prev, aadhaarNumber: '' }));
              setCreditScoreData(null);
              setTouched({});
            }}
            className="w-full py-2.5 px-4 bg-slate-900 hover:bg-slate-800 text-white font-medium rounded-xl transition-all shadow-sm text-sm"
          >
            Submit Another Update
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-slate-50/70 py-8 px-4 sm:px-6 lg:px-8 font-sans text-slate-900">
      <div className="max-w-4xl mx-auto space-y-6">
        {/* Header Header Navigation */}
        <div className="bg-white rounded-2xl p-6 shadow-sm border border-slate-200/80 flex flex-col sm:flex-row justify-between sm:items-center gap-4">
          <div>
            <div className="flex items-center space-x-2 text-xs font-semibold text-indigo-600 tracking-wide uppercase mb-1">
              <ShieldCheck className="w-4 h-4" />
              <span>Customer Verification Hub</span>
            </div>
            <h1 className="text-2xl font-bold text-slate-900 tracking-tight">
              Customer KYC Updates
            </h1>
            <p className="text-sm text-slate-500 mt-0.5">
              Complete identity verification and review credit intelligence from partner bureau.
            </p>
          </div>
          <div className="flex items-center space-x-2 bg-slate-100/80 p-1.5 rounded-xl border border-slate-200 self-start sm:self-auto">
            <div className="px-3 py-1 bg-white rounded-lg shadow-xs text-xs font-semibold text-slate-800 flex items-center space-x-1.5">
              <Lock className="w-3.5 h-3.5 text-emerald-600" />
              <span>256-bit Encrypted</span>
            </div>
          </div>
        </div>

        {/* Form Main Grid */}
        <form onSubmit={handleSubmit} className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          {/* Left Column: Personal & Aadhaar Inputs */}
          <div className="lg:col-span-7 space-y-6">
            {/* Identification Section Card */}
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200/80 p-6 space-y-5">
              <div className="border-b border-slate-100 pb-4">
                <h2 className="text-base font-semibold text-slate-900 flex items-center gap-2">
                  <User className="w-4 h-4 text-slate-500" />
                  Customer Profile Information
                </h2>
                <p className="text-xs text-slate-500 mt-0.5">Primary demographic details pulled from core registry.</p>
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <div>
                  <label className="block text-xs font-medium text-slate-700 mb-1">Full Name</label>
                  <div className="relative">
                    <input
                      type="text"
                      readOnly
                      value={formData.fullName}
                      className="w-full text-sm bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-slate-600 cursor-not-allowed focus:outline-none"
                    />
                    <Lock className="w-3.5 h-3.5 text-slate-400 absolute right-3 top-3" />
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-medium text-slate-700 mb-1">PAN / Tax ID</label>
                  <div className="relative">
                    <input
                      type="text"
                      readOnly
                      value={formData.panNumber}
                      className="w-full text-sm bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-slate-600 font-mono cursor-not-allowed focus:outline-none"
                    />
                    <Lock className="w-3.5 h-3.5 text-slate-400 absolute right-3 top-3" />
                  </div>
                </div>

                <div>
                  <label className="block text-xs font-medium text-slate-700 mb-1">Email Address</label>
                  <input
                    type="email"
                    readOnly
                    value={formData.email}
                    className="w-full text-sm bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-slate-600 cursor-not-allowed focus:outline-none"
                  />
                </div>

                <div>
                  <label className="block text-xs font-medium text-slate-700 mb-1">Phone Number</label>
                  <input
                    type="text"
                    readOnly
                    value={formData.phone}
                    className="w-full text-sm bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 text-slate-600 cursor-not-allowed focus:outline-none"
                  />
                </div>
              </div>
            </div>

            {/* Aadhaar Input Card (Main Spec Requirement) */}
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200/80 p-6 space-y-4 relative overflow-hidden">
              <div className="absolute top-0 right-0 w-32 h-32 bg-indigo-50/50 rounded-full blur-2xl -mr-10 -mt-10 pointer-events-none" />

              <div className="flex items-center justify-between border-b border-slate-100 pb-4">
                <div>
                  <h2 className="text-base font-semibold text-slate-900 flex items-center gap-2">
                    <Fingerprint className="w-5 h-5 text-indigo-600" />
                    Aadhaar Verification
                    <span className="bg-indigo-50 text-indigo-700 text-[10px] font-semibold px-2 py-0.5 rounded-full border border-indigo-200/60 uppercase tracking-wider">
                      Required
                    </span>
                  </h2>
                  <p className="text-xs text-slate-500 mt-0.5">
                    Enter the 12-digit UIDAI issued Unique Identification Number.
                  </p>
                </div>
                <div className="relative">
                  <button
                    type="button"
                    onMouseEnter={() => setShowTooltip(true)}
                    onMouseLeave={() => setShowTooltip(false)}
                    onClick={() => setShowTooltip(!showTooltip)}
                    className="text-slate-400 hover:text-slate-600 transition-colors p-1 rounded-full hover:bg-slate-100"
                  >
                    <HelpCircle className="w-4 h-4" />
                  </button>
                  {showTooltip && (
                    <div className="absolute right-0 top-7 w-64 p-2.5 bg-slate-900 text-white text-xs rounded-xl shadow-lg z-20 space-y-1">
                      <p className="font-semibold">Regex Validation Rule:</p>
                      <p className="text-slate-300 font-mono text-[11px]">^\d&#123;12&#125;$</p>
                      <p className="text-slate-400 text-[10px]">Strictly requires exactly 12 numerical characters without alphabets or special symbols.</p>
                    </div>
                  )}
                </div>
              </div>

              <div className="space-y-2">
                <label htmlFor="aadhaarInput" className="block text-xs font-semibold text-slate-700 uppercase tracking-wide">
                  Aadhaar Number (12 Digits)
                </label>
                <div className="relative">
                  <input
                    id="aadhaarInput"
                    type="text"
                    value={formData.aadhaarNumber}
                    onChange={handleAadhaarChange}
                    onBlur={() => handleBlur('aadhaarNumber')}
                    placeholder="0000 0000 0000"
                    maxLength={14} // 12 digits + 2 space separators
                    className={`w-full text-base font-mono tracking-widest px-4 py-3 rounded-xl border transition-all duration-150 focus:outline-none focus:ring-2 ${!!aadhaarError && touched.aadhaarNumber
                      ? 'border-rose-300 bg-rose-50/20 text-rose-900 focus:ring-rose-500/20 focus:border-rose-500'
                      : isAadhaarValid
                        ? 'border-emerald-300 bg-emerald-50/10 text-slate-900 focus:ring-emerald-500/20 focus:border-emerald-500'
                        : 'border-slate-200 bg-white text-slate-900 focus:ring-indigo-500/20 focus:border-indigo-500'
                      }`}
                  />
                  <div className="absolute right-3.5 top-3.5 flex items-center space-x-2">
                    {isAadhaarValid && (
                      <CheckCircle2 className="w-5 h-5 text-emerald-500 animate-in zoom-in-50 duration-200" />
                    )}
                    {!!aadhaarError && touched.aadhaarNumber && (
                      <AlertCircle className="w-5 h-5 text-rose-500 animate-in zoom-in-50 duration-200" />
                    )}
                  </div>
                </div>

                {/* Real-time Error Message Rendering */}
                {aadhaarError && touched.aadhaarNumber ? (
                  <div className="flex items-center space-x-1.5 text-xs text-rose-600 font-medium pt-1 animate-in slide-in-from-top-1 duration-150">
                    <AlertCircle className="w-3.5 h-3.5 flex-shrink-0" />
                    <span>{aadhaarError}</span>
                  </div>
                ) : isAadhaarValid ? (
                  <div className="flex items-center space-x-1.5 text-xs text-emerald-600 font-medium pt-1 animate-in fade-in duration-150">
                    <CheckCircle2 className="w-3.5 h-3.5 flex-shrink-0" />
                    <span>Valid 12-digit Aadhaar number format.</span>
                  </div>
                ) : (
                  <p className="text-[11px] text-slate-400 pt-0.5">
                    Format: 12 numerical digits. Spaces will be auto-formatted.
                  </p>
                )}
              </div>

              <div className="pt-2">
                <label className="flex items-start space-x-3 cursor-pointer group">
                  <input
                    type="checkbox"
                    checked={formData.agreeTerms}
                    onChange={(e) => setFormData(prev => ({ ...prev, agreeTerms: e.target.checked }))}
                    className="mt-0.5 h-4 w-4 rounded border-slate-300 text-indigo-600 focus:ring-indigo-500 cursor-pointer"
                  />
                  <span className="text-xs text-slate-600 leading-relaxed group-hover:text-slate-800 transition-colors">
                    I hereby consent to fetching biometric/identity authentication status from UIDAI and consent to sharing financial records with accredited Credit Rating Agencies for evaluation.
                  </span>
                </label>
              </div>
            </div>

            {/* Form Action Buttons */}
            <div className="flex items-center justify-end space-x-3 pt-2">
              <button
                type="button"
                onClick={() => {
                  setFormData(prev => ({ ...prev, aadhaarNumber: '' }));
                  setTouched({});
                  setCreditScoreData(null);
                }}
                className="px-4 py-2.5 rounded-xl border border-slate-200 text-xs font-semibold text-slate-600 hover:bg-slate-50 transition-colors"
              >
                Reset Fields
              </button>
              <button
                type="submit"
                disabled={!isAadhaarValid || !formData.agreeTerms || isSubmitting}
                className={`px-6 py-2.5 rounded-xl text-xs font-semibold text-white shadow-md flex items-center space-x-2 transition-all ${!isAadhaarValid || !formData.agreeTerms || isSubmitting
                  ? 'bg-slate-300 cursor-not-allowed shadow-none'
                  : 'bg-indigo-600 hover:bg-indigo-700 hover:shadow-indigo-200 shadow-indigo-100 cursor-pointer'
                  }`}
              >
                {isSubmitting ? (
                  <>
                    <RefreshCw className="w-4 h-4 animate-spin" />
                    <span>Verifying & Saving...</span>
                  </>
                ) : (
                  <>
                    <span>Save KYC Updates</span>
                    <ChevronRight className="w-4 h-4" />
                  </>
                )}
              </button>
            </div>
          </div>

          {/* Right Column: Calculated Credit Score Read-Only Display Card */}
          <div className="lg:col-span-5 space-y-6">
            <div className="bg-white rounded-2xl shadow-sm border border-slate-200/80 p-6 space-y-5 sticky top-6">
              <div className="flex items-center justify-between border-b border-slate-100 pb-4">
                <div>
                  <h2 className="text-base font-semibold text-slate-900 flex items-center gap-2">
                    <CreditCard className="w-5 h-5 text-indigo-600" />
                    Calculated Credit Score
                  </h2>
                  <p className="text-xs text-slate-500 mt-0.5">
                    Read-only data synced from Credit Bureau
                  </p>
                </div>
                <span className="px-2.5 py-1 bg-slate-100 text-slate-600 text-[10px] font-mono font-semibold rounded-md border border-slate-200">
                  READ-ONLY
                </span>
              </div>

              {/* Loading State */}
              {isFetchingScore && (
                <div className="py-12 text-center space-y-3 bg-slate-50/50 rounded-xl border border-dashed border-slate-200">
                  <RefreshCw className="w-8 h-8 text-indigo-600 animate-spin mx-auto" />
                  <div>
                    <p className="text-xs font-semibold text-slate-800">Querying Bureau Database...</p>
                    <p className="text-[11px] text-slate-400 mt-0.5">Retrieving credit score for Aadhaar reference</p>
                  </div>
                </div>
              )}

              {/* Credit Score Rendered Card */}
              {!isFetchingScore && creditScoreData && (
                <div className="space-y-5 animate-in fade-in zoom-in-95 duration-300">
                  {/* Bureau Banner */}
                  <div className="bg-slate-900 text-white rounded-xl p-4 relative overflow-hidden shadow-md">
                    <div className="absolute -right-6 -bottom-6 w-24 h-24 bg-indigo-500/20 rounded-full blur-xl pointer-events-none" />
                    <div className="flex justify-between items-start mb-3">
                      <div>
                        <p className="text-[10px] uppercase font-bold text-slate-400 tracking-wider">Source Partner</p>
                        <p className="text-xs font-medium text-slate-200 flex items-center gap-1.5 mt-0.5">
                          <Building2 className="w-3.5 h-3.5 text-indigo-400" />
                          {creditScoreData.bureau}
                        </p>
                      </div>
                      <span className="inline-flex items-center px-2 py-0.5 rounded text-[10px] font-semibold bg-emerald-500/20 text-emerald-300 border border-emerald-500/30">
                        Live Synced
                      </span>
                    </div>

                    {/* Score Gauge Visual */}
                    <div className="pt-2 pb-1 text-center">
                      <div className="inline-block relative">
                        <span className="text-5xl font-black tracking-tight text-white font-mono">
                          {creditScoreData.score}
                        </span>
                        <span className="text-xs text-slate-400 font-sans ml-1">/ 850</span>
                      </div>
                      <div className="mt-1">
                        <span className={`inline-block px-3 py-0.5 rounded-full text-xs font-bold ${getScoreColor(creditScoreData.score).bg} text-white shadow-xs`}>
                          {creditScoreData.rating}
                        </span>
                      </div>
                    </div>

                    {/* Progress Bar Gauge */}
                    <div className="mt-4 space-y-1">
                      <div className="h-2 w-full bg-slate-800 rounded-full overflow-hidden p-0.5 border border-slate-700/50">
                        <div
                          className={`h-full rounded-full transition-all duration-1000 ease-out ${getScoreColor(creditScoreData.score).bg}`}
                          style={{ width: `${getScorePercentage(creditScoreData.score)}%` }}
                        />
                      </div>
                      <div className="flex justify-between text-[10px] text-slate-400 font-mono px-0.5">
                        <span>300 (Poor)</span>
                        <span>850 (Excellent)</span>
                      </div>
                    </div>
                  </div>

                  {/* Bureau Metadata & Insights */}
                  <div className="bg-slate-50 border border-slate-200/80 rounded-xl p-4 space-y-3">
                    <div className="flex justify-between items-center text-xs pb-2 border-b border-slate-200/60">
                      <span className="text-slate-500 font-medium">Last Refreshed:</span>
                      <span className="text-slate-800 font-semibold">{creditScoreData.lastUpdated}</span>
                    </div>

                    <div>
                      <p className="text-[11px] font-semibold text-slate-700 uppercase tracking-wider mb-2 flex items-center gap-1.5">
                        <TrendingUp className="w-3.5 h-3.5 text-indigo-600" />
                        Credit Impact Factors
                      </p>
                      <ul className="space-y-1.5">
                        {creditScoreData.factors.map((factor, idx) => (
                          <li key={idx} className="text-xs text-slate-600 flex items-center space-x-2">
                            <span className="w-1.5 h-1.5 rounded-full bg-indigo-500 flex-shrink-0" />
                            <span>{factor}</span>
                          </li>
                        ))}
                      </ul>
                    </div>
                  </div>
                </div>
              )}

              {/* Empty / Unverified State */}
              {!isFetchingScore && !creditScoreData && (
                <div className="py-10 px-4 text-center border-2 border-dashed border-slate-200 rounded-xl bg-slate-50/50 space-y-3">
                  <div className="w-12 h-12 bg-slate-100 text-slate-400 rounded-full flex items-center justify-center mx-auto">
                    <Award className="w-6 h-6" />
                  </div>
                  <div>
                    <p className="text-xs font-semibold text-slate-700">Awaiting Aadhaar Validation</p>
                    <p className="text-[11px] text-slate-400 max-w-xs mx-auto mt-1">
                      Provide a valid 12-digit Aadhaar number on the left panel to automatically query and render the calculated credit score.
                    </p>
                  </div>
                </div>
              )}

              {/* Compliance Note */}
              <div className="p-3 bg-amber-50/70 border border-amber-200/60 rounded-xl flex items-start space-x-2.5 text-amber-900 text-xs">
                <Info className="w-4 h-4 text-amber-600 flex-shrink-0 mt-0.5" />
                <p className="text-[11px] leading-relaxed text-amber-800">
