import re

def mask_aadhaar(aadhaar_str):
    if not aadhaar_str:
        return "XXXX-XXXX-XXXX"
    digits = re.sub(r"\\D", "", str(aadhaar_str))
    if len(digits) >= 4:
        return f"XXXX-XXXX-{digits[-4:]}"
    return "XXXX-XXXX-XXXX"

def calculate_risk_index(monthly_income, credit_score):
    try:
        income = float(monthly_income) if monthly_income is not None else 0.0
        score = float(credit_score) if credit_score is not None else 600.0
        if income <= 0:
            return 100.0
        score_risk = max(0.0, (850.0 - score) / 550.0 * 50.0)
        income_risk = max(0.0, (100000.0 - income) / 100000.0 * 50.0)
        return round(min(100.0, max(0.0, score_risk + income_risk)), 2)
    except (ValueError, TypeError):
        return 50.0

def transform_batch(raw_records: list) -> list:
    cleansed_records = []
    for record in raw_records:
        if not isinstance(record, dict):
            continue
        clean_record = {}
        for k, v in record.items():
            clean_key = k.strip() if isinstance(k, str) else k
            clean_val = v.strip() if isinstance(v, str) else v
            clean_record[clean_key] = clean_val
        aadhaar_raw = clean_record.get("aadhaar_no", "")
        masked = mask_aadhaar(aadhaar_raw)
        clean_record["aadhaar_no"] = masked
        clean_record["masked_aadhaar"] = masked
        income = clean_record.get("monthly_income", 0)
        credit = clean_record.get("credit_score", 600)
        clean_record["risk_index"] = calculate_risk_index(income, credit)
        cleansed_records.append(clean_record)
    return cleansed_records
